WITH cleaned AS (SELECT id, account_id, txn_type, txn_time, merchant, FLOOR(amount) AS amount_whole, CASE WHEN merchant = 'Lazada' THEN 1 ELSE 0 END AS is_lazada, COALESCE(merchant, 'NONE') AS resolved_merchant FROM transactions WHERE txn_time >= TO_DATE('2023-11-05') AND merchant IS NOT NULL) SELECT merchant, account_id FROM cleaned EXCEPT ALL SELECT merchant, account_id FROM transactions WHERE amount IS NOT NULL
